# FRAME, COMMON и GPT (перевод фото) — те же, что на основной странице
src=open(os.path.join(HERE,'portrety_page.py')).read()
def grab(name):
  for n in ast.parse(src).body:
    if isinstance(n,ast.Assign) and getattr(n.targets[0],'id',None)==name: return ast.literal_eval(n.value)
FRAME,PHOTO_GEM,PHOTO_GPT=grab('FRAME'),grab('COMMON'),grab('GPT')

